/**
 * The musical grid a timeline draws and snaps to: note-value divisions that
 * follow the tempo, how they are named, the rhythms of a metronome and how far
 * apart a ruler labels its bars. All of it a function of seconds and zoom, with
 * no view in it.
 */

import {
  secondsPerBar,
  secondsPerBeat,
  secondsPerQuarter,
  type Tempo,
} from "./tempo";

/** The fixed grid divisions, coarsest first: a number of bars, or a note value. */
export const GRID_DIVISIONS = [
  { bars: 4, id: "4-bars" },
  { bars: 2, id: "2-bars" },
  { bars: 1, id: "1-bar" },
  { id: "1/2", note: 2 },
  { id: "1/4", note: 4 },
  { id: "1/8", note: 8 },
  { id: "1/16", note: 16 },
  { id: "1/32", note: 32 },
] as const;

/** The id of a fixed grid division: `"4-bars"` to `"1/32"`. */
export type FixedGridDivision = (typeof GRID_DIVISIONS)[number]["id"];

/** `adaptive` follows the zoom; a fixed division stays put however far you zoom. */
export type GridDivision = "adaptive" | FixedGridDivision;

/** Three in the space of two: a triplet division is 2/3 of its straight one. */
export const TRIPLET_FACTOR = 2 / 3;

/** How long one fixed division lasts at `tempo`, in seconds. */
export function divisionSeconds(
  division: FixedGridDivision,
  tempo: Tempo
): number {
  const found = GRID_DIVISIONS.find((entry) => entry.id === division);
  if (!found) {
    return secondsPerBar(tempo);
  }
  // A note value is a share of a whole note, which is four quarters
  // whatever the signature says; a bar follows the signature.
  return "bars" in found
    ? found.bars * secondsPerBar(tempo)
    : (4 / found.note) * secondsPerQuarter(tempo);
}

/**
 * The fixed division next to `division`: a finer one (`direction` 1, twice as
 * dense) or a coarser one (-1), held at the ends of the list.
 */
export function adjacentDivision(
  division: FixedGridDivision,
  direction: 1 | -1
): FixedGridDivision {
  const index = GRID_DIVISIONS.findIndex((entry) => entry.id === division);
  const next = Math.min(
    GRID_DIVISIONS.length - 1,
    Math.max(0, index + direction)
  );
  return GRID_DIVISIONS[next]?.id ?? division;
}

/**
 * The fixed division whose step is nearest `seconds` at `tempo`: what a grid
 * that follows the zoom becomes when it is fixed where it is.
 */
export function divisionAt(seconds: number, tempo: Tempo): FixedGridDivision {
  let found: FixedGridDivision = "1-bar";
  let distance = Number.POSITIVE_INFINITY;
  for (const entry of GRID_DIVISIONS) {
    const away = Math.abs(Math.log(divisionSeconds(entry.id, tempo) / seconds));
    if (away < distance) {
      distance = away;
      found = entry.id;
    }
  }
  return found;
}

/** How close adaptive grid lines may be, and whether the grid is in triplets. */
export interface GridIntervalOptions {
  /** The closest two adaptive lines may be, in px. @default 24 */
  minSpacing?: number;
  triplet?: boolean;
}

/**
 * Seconds between grid lines at `zoom` px per second: the lines a timeline
 * draws and the step it snaps to, so what you see is where you land. A
 * fixed division ignores the zoom; `adaptive` picks the finest division
 * still far enough from its neighbour to be aimed at.
 */
export function gridInterval(
  division: GridDivision,
  zoom: number,
  tempo: Tempo,
  { minSpacing = 24, triplet = false }: GridIntervalOptions = {}
): number {
  const factor = triplet ? TRIPLET_FACTOR : 1;
  if (division !== "adaptive") {
    return divisionSeconds(division, tempo) * factor;
  }
  const finestFirst = GRID_DIVISIONS.map((entry) =>
    divisionSeconds(entry.id, tempo)
  ).reverse();
  for (const seconds of finestFirst) {
    // Measured after the triplet, or a ternary grid would be drawn a third
    // denser than a grid is allowed to be.
    if (seconds * factor * zoom >= minSpacing) {
      return seconds * factor;
    }
  }
  return (finestFirst.at(-1) ?? secondsPerBar(tempo)) * factor;
}

const LABEL_TOLERANCE = 1e-6;

/** `value` as a whole number of at least one, or null if it is not one. */
function whole(value: number): number | null {
  const rounded = Math.round(value);
  return rounded >= 1 && Math.abs(value - rounded) < LABEL_TOLERANCE
    ? rounded
    : null;
}

/** The note value a count of quarters is, when it is a halving of a whole note. */
function noteDenominator(quarters: number): number | null {
  const denominator = whole(4 / quarters);
  return denominator !== null && (denominator & (denominator - 1)) === 0
    ? denominator
    : null;
}

function barsName(bars: number): string {
  return bars === 1 ? "1 bar" : `${bars} bars`;
}

/**
 * Names an interval the way a grid readout does: "1 bar", "4 bars", "1/16",
 * "1/8T". It works from the interval rather than from a setting, so the
 * adaptive grid, which has no name of its own, reads out the division it has
 * landed on, and a menu and a readout cannot name one grid two ways.
 */
export function gridLabel(seconds: number, tempo: Tempo): string {
  const bars = seconds / secondsPerBar(tempo);
  const straightBars = whole(bars);
  if (straightBars !== null) {
    return barsName(straightBars);
  }
  const quarters = seconds / secondsPerQuarter(tempo);
  const note = noteDenominator(quarters);
  if (note !== null) {
    return `1/${note}`;
  }
  const tripletBars = whole(bars / TRIPLET_FACTOR);
  if (tripletBars !== null) {
    return `${barsName(tripletBars)} T`;
  }
  const tripletNote = noteDenominator(quarters / TRIPLET_FACTOR);
  if (tripletNote !== null) {
    return `1/${tripletNote}T`;
  }
  const beats = Number((seconds / secondsPerBeat(tempo)).toFixed(2));
  return `${beats} beats`;
}

/**
 * How often a metronome clicks: with the beat, or a note value, straight or
 * triplet. `denominator` is the note value (1 is a bar), `0` follows the beat.
 */
export const METRONOME_RHYTHMS = [
  { denominator: 0, id: "auto", triplet: false },
  { denominator: 1, id: "1-bar", triplet: false },
  { denominator: 2, id: "1/2", triplet: false },
  { denominator: 2, id: "1/2t", triplet: true },
  { denominator: 4, id: "1/4", triplet: false },
  { denominator: 4, id: "1/4t", triplet: true },
  { denominator: 8, id: "1/8", triplet: false },
  { denominator: 8, id: "1/8t", triplet: true },
  { denominator: 16, id: "1/16", triplet: false },
  { denominator: 16, id: "1/16t", triplet: true },
] as const;

/** The id of a metronome rhythm: `"auto"` (the beat), a bar, or a note value, straight or triplet. */
export type MetronomeRhythm = (typeof METRONOME_RHYTHMS)[number]["id"];

/**
 * Seconds between clicks for a rhythm, or `null` for `auto`, which has no
 * interval of its own: it is the beat, whatever the signature makes one.
 */
export function metronomeRhythmSeconds(
  rhythm: MetronomeRhythm,
  tempo: Tempo
): number | null {
  const found = METRONOME_RHYTHMS.find((entry) => entry.id === rhythm);
  if (!found || found.denominator === 0) {
    return null;
  }
  const straight =
    found.denominator === 1
      ? secondsPerBar(tempo)
      : (4 / found.denominator) * secondsPerQuarter(tempo);
  return found.triplet ? straight * TRIPLET_FACTOR : straight;
}

/**
 * Seconds between labelled bars on a ruler at `zoom` px per second: always a
 * whole number of bars, doubled until labels are at least `minSpacing` px
 * apart, so they never collide or fall mid-bar.
 */
export function barLabelInterval(
  zoom: number,
  tempo: Tempo,
  minSpacing = 64
): number {
  const bar = secondsPerBar(tempo);
  let interval = bar;
  while (interval * zoom < minSpacing && interval < bar * 1024) {
    interval *= 2;
  }
  return interval;
}

/** `1/8`, `1/8t` or `1/8d`: a note value and, maybe, a triplet or dotted mark. */
const SYNCED_PATTERN = /^1\/(\d+)([td]?)$/;

/** A straight note value, in the form a time parameter lists it. */
const SYNCED_NOTES = [32, 16, 8, 4, 2, 1] as const;

/** Three halves: a dotted note is its straight one and half again. */
export const DOTTED_FACTOR = 3 / 2;

/**
 * The note values a time parameter that follows the tempo can take, shortest
 * first: `1/16` is a sixteenth note, `1/8t` a triplet eighth (two thirds of
 * it) and `1/8d` a dotted eighth (one and a half times it). The `value` goes in
 * a device's state, the `label` is what a panel shows.
 */
export const SYNCED_DIVISIONS = SYNCED_NOTES.flatMap((note) => {
  const name = note === 1 ? "1/1" : `1/${note}`;
  return [
    { label: `${name} triplet`, value: `${name}t` },
    { label: name, value: name },
    { label: `${name} dotted`, value: `${name}d` },
  ];
});

/** A note value as `syncedSeconds` reads it: `"1/8"`, its triplet `"1/8t"` or its dotted `"1/8d"`. */
export type SyncedDivision = string;

/**
 * How long a synced note value lasts at `tempo`, in seconds: `1/8` an eighth,
 * `1/8t` its triplet, `1/8d` its dotted one. A value that is not in
 * `SYNCED_DIVISIONS` is read as a quarter note, so a stale state still sounds
 * on the beat instead of at zero.
 */
export function syncedSeconds(division: SyncedDivision, tempo: Tempo): number {
  const match = SYNCED_PATTERN.exec(division);
  const note = match ? Number(match[1]) : 4;
  const suffix = match?.[2] ?? "";
  let factor = 1;
  if (suffix === "t") {
    factor = TRIPLET_FACTOR;
  } else if (suffix === "d") {
    factor = DOTTED_FACTOR;
  }
  return (4 / note) * secondsPerQuarter(tempo) * factor;
}

/**
 * Bars through time-signature changes: a song starts in its tempo's
 * signature, and each change starts counting bars of its own from where it is
 * put. A change that lands inside a bar cuts that bar short, a partial bar,
 * as a DAW shows it. Positions are seconds, at one tempo.
 */

import { type MetronomeRhythm, metronomeRhythmSeconds } from "./grid";
import { type BarsBeats, secondsPerQuarter, type Tempo } from "./tempo";

/** A new signature from `at` on, in seconds: `beatsPerBar` beats of a `beatUnit` note. */
export interface SignatureChange {
  at: number;
  beatsPerBar: number;
  beatUnit: number;
}

/** A bar as a ruler draws it. */
export interface Bar {
  beatsPerBar: number;
  beatUnit: number;
  /** In seconds. */
  length: number;
  /** Counted from one, the way every DAW counts them. */
  number: number;
  /** Whether a signature change cuts it short. */
  partial: boolean;
  /** In seconds. */
  start: number;
}

const BEAT_UNITS = [1, 2, 4, 8, 16];

/** Whether a signature is one a bar can have: 1 to 99 beats of a whole, half, quarter, eighth or sixteenth note. */
export function isSignature(beatsPerBar: number, beatUnit: number): boolean {
  return (
    Number.isInteger(beatsPerBar) &&
    beatsPerBar >= 1 &&
    beatsPerBar <= 99 &&
    BEAT_UNITS.includes(beatUnit)
  );
}

/** How long a bar of a signature lasts at `tempo`, in seconds. */
function barSeconds(
  tempo: Tempo,
  beatsPerBar: number,
  beatUnit: number
): number {
  return (beatsPerBar * 4 * secondsPerQuarter(tempo)) / beatUnit;
}

/** The changes that hold, in order: valid ones, the last of several at one place, one at 0 or before standing for the start. */
function changesIn(
  tempo: Tempo,
  changes: readonly SignatureChange[]
): SignatureChange[] {
  const byPlace = new Map<number, SignatureChange>();
  // The tempo's own signature, or 4/4 when it is not one a bar can have.
  const valid = isSignature(tempo.beatsPerBar, tempo.beatUnit);
  byPlace.set(0, {
    at: 0,
    beatUnit: valid ? tempo.beatUnit : 4,
    beatsPerBar: valid ? tempo.beatsPerBar : 4,
  });
  for (const change of changes) {
    if (
      Number.isFinite(change.at) &&
      isSignature(change.beatsPerBar, change.beatUnit)
    ) {
      const at = Math.max(0, change.at);
      byPlace.set(at, { ...change, at });
    }
  }
  return [...byPlace.values()].sort((a, b) => a.at - b.at);
}

/** Small enough not to count as a bar: what is left of one by a rounding error. */
const SLIVER = 1e-9;

/**
 * The bars from 0 to `until` seconds, through the signature changes: whole
 * bars of each signature, and a partial bar where a change cuts one short.
 */
export function barsOf(
  tempo: Tempo,
  changes: readonly SignatureChange[],
  until: number
): Bar[] {
  const held = changesIn(tempo, changes);
  const bars: Bar[] = [];
  held.forEach((change, index) => {
    const next = held[index + 1]?.at ?? Number.POSITIVE_INFINITY;
    const length = barSeconds(tempo, change.beatsPerBar, change.beatUnit);
    for (let start = change.at; start < Math.min(next, until) - SLIVER; ) {
      const cut = start + length > next + SLIVER;
      bars.push({
        beatUnit: change.beatUnit,
        beatsPerBar: change.beatsPerBar,
        length: cut ? next - start : length,
        number: bars.length + 1,
        partial: cut,
        start,
      });
      start += length;
    }
  });
  return bars;
}

/** A click of a metronome. */
export interface MetronomeClick {
  /** Whether it is the first of its bar. */
  accent: boolean;
  /** When it plays, in seconds. */
  at: number;
}

/**
 * The clicks of a metronome from 0 to `until` seconds, through the signature
 * changes. `auto` clicks on each beat of the signature in force, `1-bar` once a
 * bar, whatever its length, and any other rhythm at its own interval, which
 * each bar starts again. The first click of a bar is accented.
 */
export function metronomeClicks(
  tempo: Tempo,
  changes: readonly SignatureChange[],
  until: number,
  rhythm: MetronomeRhythm = "auto"
): MetronomeClick[] {
  const interval =
    rhythm === "1-bar" ? null : metronomeRhythmSeconds(rhythm, tempo);
  const clicks: MetronomeClick[] = [];
  for (const bar of barsOf(tempo, changes, until)) {
    const whole = barSeconds(tempo, bar.beatsPerBar, bar.beatUnit);
    const beats = rhythm === "1-bar" ? 1 : bar.beatsPerBar;
    const step = interval ?? whole / beats;
    const end = Math.min(bar.start + bar.length, until) - SLIVER;
    for (let index = 0; bar.start + index * step < end; index += 1) {
      clicks.push({ accent: index === 0, at: bar.start + index * step });
    }
  }
  return clicks;
}

/** Where `seconds` falls in bars, beats and sixteenths through the signature changes, each counted from one. */
export function barsBeatsWith(
  seconds: number,
  tempo: Tempo,
  changes: readonly SignatureChange[]
): BarsBeats {
  const at = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;
  const bars = barsOf(tempo, changes, at + SLIVER * 2);
  const bar = bars.at(-1);
  if (!bar) {
    return { bar: 1, beat: 1, sixteenth: 1 };
  }
  const sixteenth = secondsPerQuarter(tempo) / 4;
  // Nudged past the representation error, so a position on a beat reads as that beat.
  const sixteenths = Math.floor((at - bar.start) / sixteenth + 1e-9);
  const perBeat = 16 / bar.beatUnit;
  return {
    bar: bar.number,
    beat: Math.floor(sixteenths / perBeat) + 1,
    sixteenth: (sixteenths % perBeat) + 1,
  };
}

/**
 * The look-ahead scheduler of "A tale of two clocks" (Chris Wilson): a
 * JavaScript timer wakes often, and each time commits the steps that fall in
 * the next fraction of a second to the audio clock, whose times are exact
 * where a timer's are not. This is the pure core of it: a drift-free stepping
 * cursor and the loop that advances it. It knows nothing about the AudioContext
 * or about what gets played: the caller polls it with `ctx.currentTime` on a
 * timer and schedules each boundary it returns. Being pure, drive `advance`
 * across a fake timeline and assert the boundaries it emits, no audio needed.
 */

/** How far ahead of `now` boundaries are committed, in seconds: the article's 100 ms. */
export const SCHEDULE_AHEAD_SECONDS = 0.1;
/** How often to poll the scheduler, in milliseconds: the article's 25 ms. */
export const SCHEDULER_POLL_MS = 25;
/**
 * How late a boundary may be and still be played, half a second. A stall that
 * short (a layout, a garbage collection) is caught up on: the steps it missed
 * are emitted so none is lost, a little late. A longer one, a hidden tab whose
 * timer ran once a second or a suspended laptop, is a dropout the listener
 * hears anyway, and replaying every step missed would sound them all at once:
 * the cursor jumps ahead by whole steps to where the time now is, and the
 * music carries on in time.
 */
export const MAX_CATCH_UP_SECONDS = 0.5;

/** What the scheduler steps through: the window of steps it loops over and how long a step lasts, read on every call. */
export interface SchedulerConfig {
  /** One past the last step of the window, exclusive. `totalSteps` for a full-grid clock. */
  regionEnd: number;
  /** First step of the looping window, inclusive. `0` for a full-grid clock. */
  regionStart: number;
  /**
   * Seconds between two consecutive steps, `60 / bpm / stepsPerBeat`. Read
   * fresh on every `advance` so a tempo change takes effect at the next
   * boundary, not on the next stop/start.
   */
  secondsPerStep: number;
}

/** Where the scheduler is: the next step it will emit and when. */
export interface SchedulerCursor {
  /** The step the next emitted boundary will carry. */
  nextStep: number;
  /** The audio time of that boundary. */
  nextStepTime: number;
}

/** A step to play and the audio time it starts at. */
export interface StepBoundary {
  step: number;
  /** Absolute audio time, pass straight to node `.start()`/`.stop()` for sample-accurate scheduling. */
  time: number;
}

/** The audio-time / step pair a running clock is anchored to, for deriving the display position. */
export interface SchedulerAnchor {
  step: number;
  time: number;
}

/** Whether the spacing is a step forward in time: a zero, negative or `NaN` spacing never reaches the horizon. */
const isStepping = ({ secondsPerStep }: SchedulerConfig) =>
  Number.isFinite(secondsPerStep) && secondsPerStep > 0;

function regionLength(config: SchedulerConfig): number {
  return Math.max(1, config.regionEnd - config.regionStart);
}

/** Wraps `step` back into `[regionStart, regionEnd)`, tolerating a step left stale by a shrunk region. */
function wrapStep(step: number, config: SchedulerConfig): number {
  const length = regionLength(config);
  return (
    config.regionStart +
    ((((step - config.regionStart) % length) + length) % length)
  );
}

/** A cursor that emits `step` at `now`, the seed for `start()` and for every re-anchor (seek, region commit). */
export function anchoredCursor(now: number, step: number): SchedulerCursor {
  return { nextStep: step, nextStepTime: now };
}

/**
 * Advances `cursor`, emitting every step boundary now within
 * `SCHEDULE_AHEAD_SECONDS` of `now`. The `while` (not `if`) is what makes this
 * self-correcting: a poll delayed past a whole step catches up by emitting the
 * boundaries it missed rather than letting one slip past unscheduled, up to
 * `MAX_CATCH_UP_SECONDS` late, past which it skips them (see there). A spacing
 * that is not a positive number emits nothing and leaves the cursor as it was,
 * where it would otherwise never leave the loop.
 */
export function advance(
  cursor: SchedulerCursor,
  now: number,
  config: SchedulerConfig
): { boundaries: StepBoundary[]; cursor: SchedulerCursor } {
  if (!isStepping(config)) {
    return { boundaries: [], cursor };
  }
  const horizon = now + SCHEDULE_AHEAD_SECONDS;
  const boundaries: StepBoundary[] = [];
  let step = wrapStep(cursor.nextStep, config);
  let time = cursor.nextStepTime;
  if (now - time > MAX_CATCH_UP_SECONDS) {
    const skipped = Math.floor((now - time) / config.secondsPerStep);
    step = wrapStep(step + skipped, config);
    time += skipped * config.secondsPerStep;
  }
  while (time < horizon) {
    boundaries.push({ step, time });
    time += config.secondsPerStep;
    step = wrapStep(step + 1, config);
  }
  return { boundaries, cursor: { nextStep: step, nextStepTime: time } };
}

/**
 * The continuous playhead position, in fractional full-grid steps, at `now`.
 * Derived from the anchor (the audio time at which the playhead sat exactly on
 * `anchor.step`), so it is self-correcting for display regardless of how many
 * loop iterations have actually played.
 */
export function positionAt(
  now: number,
  anchor: SchedulerAnchor,
  config: SchedulerConfig
): number {
  if (!isStepping(config)) {
    return config.regionStart;
  }
  const length = regionLength(config);
  const elapsedSteps = (now - anchor.time) / config.secondsPerStep;
  const within =
    (((anchor.step - config.regionStart + elapsedSteps) % length) + length) %
    length;
  return config.regionStart + within;
}

/**
 * The anchor to carry on with when the tempo changes while playing. The
 * playhead keeps the position it has at `now` and counts from there at the new
 * spacing. Without it `positionAt` rereads all the time since the old anchor at
 * the new spacing, and the playhead jumps (a tempo of 60 after 3 s at 120 puts
 * a 16 step loop on step 12 instead of step 8).
 */
export function anchorForTempoChange(
  now: number,
  anchor: SchedulerAnchor,
  previous: SchedulerConfig
): SchedulerAnchor {
  return { step: positionAt(now, anchor, previous), time: now };
}

/**
 * Tempo and time signature: how long a quarter note, a beat and a bar last in
 * seconds, and where a position in seconds falls in bars and beats.
 * Framework-agnostic, so a ruler, a grid and a piano roll can all ask it per
 * frame. A tempo that cannot be a tempo (zero, negative, `NaN`) makes a
 * quarter note infinitely long, so a position in it stays at the start, and a
 * signature that cannot be one reads as 4/4: nothing here throws or divides by
 * zero.
 */

export interface Tempo {
  /** Beats in a bar: the time signature's numerator. */
  beatsPerBar: number;
  /** Which note value gets one beat: the denominator. 4 is a quarter. */
  beatUnit: number;
  /** Quarter notes per minute, the usual meaning of a BPM field. */
  bpm: number;
}

/** 120 BPM in 4/4. */
export const DEFAULT_TEMPO: Tempo = { beatsPerBar: 4, beatUnit: 4, bpm: 120 };

const SECONDS_PER_MINUTE = 60;
const MICROSECONDS_PER_SECOND = 1_000_000;
/** What a file with no Set Tempo event plays at: 120 BPM, 500,000 microseconds a quarter note. */
export const DEFAULT_MICROSECONDS_PER_QUARTER_NOTE = 500_000;

const isPositive = (value: number) => Number.isFinite(value) && value > 0;

/** Seconds per quarter note: BPM counts quarters whatever the signature says. `Infinity` for a tempo that is not positive and finite. */
export function secondsPerQuarter(tempo: Tempo): number {
  return isPositive(tempo.bpm)
    ? SECONDS_PER_MINUTE / tempo.bpm
    : Number.POSITIVE_INFINITY;
}

/** The note value that gets a beat, 4 when the signature has none that makes sense. */
const beatUnitOf = (tempo: Tempo) =>
  isPositive(tempo.beatUnit) ? tempo.beatUnit : DEFAULT_TEMPO.beatUnit;
const beatsPerBarOf = (tempo: Tempo) =>
  isPositive(tempo.beatsPerBar) ? tempo.beatsPerBar : DEFAULT_TEMPO.beatsPerBar;

/** Seconds per beat, a beat being one `beatUnit` note: in 6/8, half a quarter. */
export function secondsPerBeat(tempo: Tempo): number {
  return secondsPerQuarter(tempo) * (4 / beatUnitOf(tempo));
}

/** Seconds per bar: a beat times the beats in a bar. */
export function secondsPerBar(tempo: Tempo): number {
  return secondsPerBeat(tempo) * beatsPerBarOf(tempo);
}

/** A tempo in BPM as microseconds per quarter note, the unit a MIDI file stores: 120 BPM is 500000. */
export function bpmToMicrosecondsPerQuarterNote(bpm: number): number {
  return (SECONDS_PER_MINUTE * MICROSECONDS_PER_SECOND) / bpm;
}

/** The BPM of a Set Tempo's microseconds per quarter note: 500000 is 120. */
export function microsecondsPerQuarterNoteToBpm(microseconds: number): number {
  return (SECONDS_PER_MINUTE * MICROSECONDS_PER_SECOND) / microseconds;
}

/** A position in bars, beats and sixteenths, each counted from one. */
export interface BarsBeats {
  /** One-based, the way every DAW counts them. */
  bar: number;
  beat: number;
  /** Sixteenth within the beat, also from one. */
  sixteenth: number;
}

/** Where `seconds` falls in bars, beats and sixteenths, each counted from one. */
export function barsBeatsAt(seconds: number, tempo: Tempo): BarsBeats {
  // Nudged past the representation error before flooring, so a position
  // exactly on a beat never reads as the end of the one before.
  const sixteenths = Math.floor(
    (Number.isFinite(seconds) ? Math.max(0, seconds) : 0) /
      (secondsPerQuarter(tempo) / 4) +
      1e-9
  );
  const sixteenthsPerBeat = 16 / beatUnitOf(tempo);
  const beatsPerBar = beatsPerBarOf(tempo);
  const beats = Math.floor(sixteenths / sixteenthsPerBeat);
  return {
    bar: Math.floor(beats / beatsPerBar) + 1,
    beat: (beats % beatsPerBar) + 1,
    sixteenth: Math.floor(sixteenths % sixteenthsPerBeat) + 1,
  };
}

/** "Bar 3, beat 2", the way a position is read out to a screen reader. */
export function describeBarsBeats(seconds: number, tempo: Tempo): string {
  const { bar, beat } = barsBeatsAt(seconds, tempo);
  return `Bar ${bar}, beat ${beat}`;
}

/**
 * Warping: markers that pin a time in a recording (its source) to a time on
 * the clip it plays in (its target). Between two markers the recording is
 * stretched or squeezed evenly to fit, so a beat in it lands on the beat of
 * the song; past the first and the last, it keeps the speed of the stretch
 * next to it. Played by changing speed alone, a stretch also changes pitch,
 * as a turntable does.
 */

/** A time in the source, pinned to a time on the clip. */
export interface WarpMarker {
  source: number;
  target: number;
}

/** How close two markers may be, in either time. */
const GAP = 1e-6;

/**
 * The markers that make a map: finite ones, in order, each later than the one
 * before in both times. One that would run back in either time is left out.
 */
export function warpMarkers(markers: readonly WarpMarker[]): WarpMarker[] {
  const sorted = markers
    .filter(
      (marker) =>
        Number.isFinite(marker.source) && Number.isFinite(marker.target)
    )
    .sort((a, b) => a.source - b.source);
  const kept: WarpMarker[] = [];
  for (const marker of sorted) {
    const last = kept.at(-1);
    if (
      !last ||
      (marker.source > last.source + GAP && marker.target > last.target + GAP)
    ) {
      kept.push(marker);
    }
  }
  return kept;
}

/** The maps made so far, by the markers they were made from: a map is made once, not at every reading. */
const maps = new WeakMap<readonly WarpMarker[], WarpMarker[]>();

/** The map of `markers`, made the first time they are read: markers are read as they were then, so new markers are a new array. */
function mapOf(markers: readonly WarpMarker[]): WarpMarker[] {
  const kept = maps.get(markers);
  if (kept) {
    return kept;
  }
  const map = warpMarkers(markers);
  maps.set(markers, map);
  return map;
}

/** Maps a time from one side to the other, along the stretches between the markers. */
function along(
  markers: readonly WarpMarker[],
  time: number,
  from: "source" | "target",
  to: "source" | "target"
): number {
  const map = mapOf(markers);
  const [first, second] = map;
  if (!first) {
    return time;
  }
  if (!second) {
    return time - first[from] + first[to];
  }
  // The stretch that holds `time`, or the first or last one past the ends: the last marker at or before it, searched by halves.
  let index = 0;
  let high = map.length - 2;
  while (index < high) {
    const middle = (index + high + 1) >> 1;
    if (time >= (map[middle] as WarpMarker)[from]) {
      index = middle;
    } else {
      high = middle - 1;
    }
  }
  const a = map[index] as WarpMarker;
  const b = map[index + 1] as WarpMarker;
  return a[to] + ((time - a[from]) * (b[to] - a[to])) / (b[from] - a[from]);
}

/** Where on the clip a time in the source plays. */
export function warpedTime(
  markers: readonly WarpMarker[],
  source: number
): number {
  return along(markers, source, "source", "target");
}

/** What time in the source plays at a time on the clip. */
export function unwarpedTime(
  markers: readonly WarpMarker[],
  target: number
): number {
  return along(markers, target, "target", "source");
}

/**
 * How fast the source plays at a time on the clip: 1 as recorded, 2 twice as
 * fast. Played by speed alone, it is also how far the pitch moves: a rate of 2
 * is an octave up.
 */
export function warpRate(
  markers: readonly WarpMarker[],
  target: number
): number {
  const step = 1e-3;
  return (
    (unwarpedTime(markers, target + step) - unwarpedTime(markers, target)) /
    step
  );
}

/** Adds a marker at a time on the clip, pinning what plays there; nothing changes in how it plays until it moves. */
export function addWarpMarker(
  markers: readonly WarpMarker[],
  target: number
): WarpMarker[] {
  return warpMarkers([
    ...markers,
    { source: unwarpedTime(markers, target), target },
  ]);
}

/**
 * Moves the marker at `index` to a new time on the clip, stretching the
 * recording on either side of it: it stops short of its neighbours.
 */
export function moveWarpMarker(
  markers: readonly WarpMarker[],
  index: number,
  target: number
): WarpMarker[] {
  const map = warpMarkers(markers);
  const marker = map[index];
  if (!(marker && Number.isFinite(target))) {
    return map;
  }
  const earliest =
    (map[index - 1]?.target ?? Number.NEGATIVE_INFINITY) + GAP * 2;
  const latest = (map[index + 1]?.target ?? Number.POSITIVE_INFINITY) - GAP * 2;
  const next = [...map];
  next[index] = {
    ...marker,
    target: Math.min(latest, Math.max(earliest, target)),
  };
  return next;
}

/** Takes the marker at `index` away, as long as two are left to make a map. */
export function removeWarpMarker(
  markers: readonly WarpMarker[],
  index: number
): WarpMarker[] {
  const map = warpMarkers(markers);
  return map.length > 2 ? map.filter((_, at) => at !== index) : map;
}

/** Plays the whole map `factor` times as long: 2 is half the speed, an octave down; 0.5 twice the speed. */
export function scaleWarp(
  markers: readonly WarpMarker[],
  factor: number
): WarpMarker[] {
  const map = warpMarkers(markers);
  if (!(Number.isFinite(factor) && factor > 0)) {
    return map;
  }
  const origin = map[0]?.target ?? 0;
  return map.map((marker) => ({
    ...marker,
    target: origin + (marker.target - origin) * factor,
  }));
}
